import pandas as pd

def clean(df):
    df = df.copy()
    df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    df['Month'] = df['Date'].dt.strftime('%Y-%m')
    return df

def answer(df):
    d = df.dropna(subset=['Month'])
    grouped = d.groupby('Month')['Revenue'].sum()
    result = {}
    for month, rev in grouped.items():
        result[month] = float(rev)
    return result
